package app.sleepscreen.tv;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.graphics.Color;import android.widget.*;
public class UpdateActivity extends Activity {
 TextView status,action;String[] release;Handler handler=new Handler(Looper.getMainLooper());boolean waiting=false;
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(Ui.dp(this,48),Ui.dp(this,36),Ui.dp(this,48),Ui.dp(this,36));root.setBackgroundColor(0xff0b0d12);TextView title=Ui.text(this,30,Color.WHITE);title.setText("Sleep Screen updates");root.addView(title);status=Ui.text(this,18,Color.WHITE);status.setText("Checking GitHub releases…");root.addView(status);action=Ui.row(root,650);action.setText("Check again");action.setOnClickListener(v->{if(release==null)check();else download();});setContentView(root);check();}
 void check(){status.setText("Checking GitHub releases…");UpdateCheck.check(this,r->{release=r;if(r==null){status.setText("No newer release found, or GitHub is unavailable.");action.setText("Check again");}else{status.setText("Update available: "+r[0]+". Android will ask you to confirm installation.");action.setText("Download update");}});}
 void download(){try{DownloadManager dm=(DownloadManager)getSystemService(DOWNLOAD_SERVICE);DownloadManager.Request req=new DownloadManager.Request(Uri.parse(release[1]));req.setTitle("Sleep Screen update");req.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);req.setDestinationInExternalFilesDir(this,Environment.DIRECTORY_DOWNLOADS,"sleepscreen-update-"+System.currentTimeMillis()+".apk");long id=dm.enqueue(req);getPreferences(0).edit().putLong("download",id).apply();waiting=true;status.setText("Downloading update…");handler.post(poll);}catch(Exception e){status.setText("Could not start the download. Try again.");}}
 Runnable poll=new Runnable(){public void run(){long id=getPreferences(0).getLong("download",-1);if(id<0||isFinishing()||isDestroyed())return;DownloadManager dm=(DownloadManager)getSystemService(DOWNLOAD_SERVICE);try(Cursor c=dm.query(new DownloadManager.Query().setFilterById(id))){if(c!=null&&c.moveToFirst()){int state=c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));if(state==DownloadManager.STATUS_FAILED){getPreferences(0).edit().remove("download").apply();status.setText("Download failed. Try again.");return;}if(state==DownloadManager.STATUS_SUCCESSFUL){if(Build.VERSION.SDK_INT>=26&&!getPackageManager().canRequestPackageInstalls()){status.setText("Allow Sleep Screen to install updates, then return here.");try{startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));}catch(Exception e){status.setText("Allow installation from Sleep Screen in Android settings.");}return;}Uri uri=dm.getUriForDownloadedFile(id);if(uri==null){status.setText("Downloaded file unavailable.");return;}getPreferences(0).edit().remove("download").apply();try{Intent install=new Intent(Intent.ACTION_VIEW);install.setDataAndType(uri,"application/vnd.android.package-archive");install.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(install);status.setText("Confirm the update in Android's installer.");}catch(Exception e){status.setText("Could not open the Android installer.");}return;}}}catch(Exception e){status.setText("Could not check the download.");return;}handler.postDelayed(this,1200);}};
 @Override protected void onResume(){super.onResume();if(getPreferences(0).getLong("download",-1)>=0){handler.removeCallbacks(poll);handler.post(poll);}}@Override protected void onDestroy(){handler.removeCallbacks(poll);super.onDestroy();}
}